ween;align-items:center;padding:16px 18px;cursor:pointer;font-weight:600;font-size:.9rem;color:var(--text);gap:12px}.faq-q i{color:#14B8A6;transition:transform .3s;flex-shrink:0;font-size:.8rem}.faq-item.open .faq-q i{transform:rotate(45deg)}.faq-a{display:none;padding:0 18px 16px;font-size:.87rem;color:var(--text-3);line-height:1.75}.faq-item.open .faq-a{display:block}.article-cta{background:linear-gradient(135deg,#0F766E,#14B8A6);border-radius:var(--radius-lg);padding:36px 40px;text-align:center;margin:40px 0 0;color:#fff}.article-cta h3{font-family:var(--font-serif);font-size:1.6rem;margin-bottom:10px}.article-cta p{font-size:.9rem;opacity:.9;margin-bottom:24px;line-height:1.7;max-width:480px;margin-left:auto;margin-right:auto}.article-cta .cta-btns{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}.cta-btn-white{background:#fff;color:#0F766E;padding:12px 26px;border-radius:8px;font-weight:600;font-size:.88rem;display:inline-flex;align-items:center;gap:8px;transition:all .2s;border:none;cursor:pointer;text-decoration:none}.cta-btn-white:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2)}.cta-btn-ghost{background:transparent;color:#fff;padding:11px 26px;border-radius:8px;font-size:.88rem;display:inline-flex;align-items:center;gap:8px;border:1.5px solid rgba(255,255,255,.4);transition:all .2s;text-decoration:none}.sidebar{display:flex;flex-direction:column;gap:20px;position:sticky;top:90px}.sidebar-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:22px}.sidebar-title{font-family:var(--font-display);font-size:.68rem;letter-spacing:.2em;text-transform:uppercase;color:#14B8A6;margin-bottom:16px;display:flex;align-items:center;gap:8px}.sidebar-title::after{content:"";flex:1;height:1px;background:var(--border-gold)}.toc-list{display:flex;flex-direction:column;gap:4px}.toc-item a{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:7px;font-size:.84rem;color:var(--text-3);trans