$JS = '<script>function toggleMobileNav(){var ham=document.getElementById(''hamburger'');var nav=document.getElementById(''mobileNav'');var nb=document.getElementById(''navbar'');var isOpen=nav.classList.contains(''open'');ham.classList.toggle(''open'');nav.classList.toggle(''open'');nav.style.top=nb.offsetHeight+''px'';document.body.style.overflow=isOpen?'''':''hidden'';}function closeMobileNav(){document.getElementById(''hamburger'').classList.remove(''open'');document.getElementById(''mobileNav'').classList.remove(''open'');document.body.style.overflow='''';}document.addEventListener(''click'',function(e){var nav=document.getElementById(''mobileNav'');var ham=document.getElementById(''hamburger'');if(nav&&nav.classList.contains(''open'')){if(!nav.contains(e.target)&&!ham.contains(e.target)){closeMobileNav();}}});function toggleFAQ(el){var item=el.closest(''.faq-item'');var isOpen=item.classList.contains(''open'');document.querySelectorAll(''.faq-item.open'').forEach(function(i){i.classList.remove(''open'');});if(!isOpen)item.classList.add(''open'');}function shareArticle(p){var u=encodeURIComponent(window.location.href);var t=encodeURIComponent(document.title);if(p===''whatsapp'')window.open(''https://wa.me/?text=''+t+''%20''+u,''_blank'');else if(p===''facebook'')window.open(''https://www.facebook.com/sharer/sharer.php?u=''+u,''_blank'');else if(p===''copy''){navigator.clipboard.writeText(window.location.href).then(function(){alert(''Link copied!'');});}}window.addEventListener(''scroll'',function(){var nb=document.getElementById(''navbar'');var bt=document.getElementById(''backTop'');if(window.scrollY>60)nb.classList.add(''scrolled'');else nb.classList.remove(''scrolled'');if(window.scrollY>400)bt.classList.add(''visible'');else bt.classList.remove(''visible'');});var ro=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add(''visible'');ro.unobserve(e.target);}});},{threshold:0});document.querySelectorAll(''.reveal'').forEach(function(el){var r=el.getBoundingClientRect();if(r.top<(window.innerHeight||document.documentElement.clientHeight)&&r.bottom>0){el.classList.add(''visible'');}else{ro.observe(el);}});</script>'

